CREATE OR REPLACE FUNCTION public.support_cost_reserve(p_suggestion uuid,p_phone text,p_number uuid,p_kind text,p_model text,p_tokens bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE st public.support_settings%ROWTYPE; r public.support_ai_daily%ROWTYPE; d date:=(now() AT TIME ZONE 'America/Sao_Paulo')::date; v uuid; BEGIN SELECT * INTO st FROM public.support_settings LIMIT 1 FOR UPDATE; IF NOT st.ai_enabled THEN RETURN jsonb_build_object('allowed',false,'reason','ia_desligada'); END IF; IF st.ai_pause_reason IS NOT NULL AND (st.ai_pause_until IS NULL OR st.ai_pause_until>now()) THEN RETURN jsonb_build_object('allowed',false,'reason',st.ai_pause_reason); END IF; INSERT INTO public.support_ai_daily(day) VALUES(d) ON CONFLICT DO NOTHING; SELECT * INTO r FROM public.support_ai_daily WHERE day=d FOR UPDATE; IF p_tokens<=0 OR r.tokens+r.reserved+p_tokens>st.ai_daily_token_budget THEN UPDATE public.support_ai_daily SET budget_stops=budget_stops+1 WHERE day=d; UPDATE public.support_settings SET ai_pause_reason='teto_diario_tokens',ai_pause_until=((d+1)::timestamp AT TIME ZONE 'America/Sao_Paulo'); RETURN jsonb_build_object('allowed',false,'reason','teto_diario_tokens','used',r.tokens,'reserved',r.reserved); END IF; IF st.ai_pause_reason='teto_diario_tokens' AND st.ai_pause_until<=now() THEN UPDATE public.support_settings SET ai_pause_reason=NULL,ai_pause_until=NULL; END IF; INSERT INTO public.support_ai_calls(suggestion_id,phone,whatsapp_number_id,kind,model,ok,reservation_tokens,settled,budget_day) VALUES(p_suggestion,p_phone,p_number,p_kind,p_model,false,p_tokens,false,d) RETURNING id INTO v; UPDATE public.support_ai_daily SET reserved=reserved+p_tokens,calls=calls+1 WHERE day=d; RETURN jsonb_build_object('allowed',true,'id',v); END $$; REVOKE ALL ON FUNCTION public.support_cost_reserve(uuid,text,uuid,text,text,bigint) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.support_cost_reserve(uuid,text,uuid,text,text,bigint) TO service_role;